    print(f"iter {e['iteration']}: {e['target_dissimilarity']:.3f}  SPI/SPC={r.get('soy protein isolate',0)+r.get('soy protein concentrate',0):.2f} coco={r.get('coconut oil',0):.2f} glut={r.get('wheat gluten',0):.2f}")
"}

